from functools import lru_cache
import logging
import urllib.request

logger = logging.getLogger(__name__)


@lru_cache(maxsize=1)
def get_public_ip():
    try:
        with urllib.request.urlopen("https://api.ipify.org") as response:
            return response.read().decode("utf-8")
    except Exception:
        return "127.0.0.1"


def generate_object_store_url(filename, base_url=None):
    # Generate HTTP URL
    if base_url:
        http_url = f"{base_url}/static/{filename}"
    else:
        # get public ip of the machine

        public_ip = get_public_ip()
        logger.info(f"base_url is not provided, using public ip and default port 8000: {public_ip}")
        http_url = f"http://{public_ip}:8000/static/{filename}"
    return http_url
